CJSON_PUBLIC(char*) cJSON_SetValuestring(cJSON *object, const char *valuestring)
{
    char *copy;
    size_t old_length;
    size_t new_length;

    if (object == NULL || valuestring == NULL)
    {
        return NULL;
    }

    if ((object->type & cJSON_String) == 0 || (object->type & cJSON_IsReference) != 0)
    {
        return NULL;
    }

    if (object->valuestring == NULL)
    {
        return NULL;
    }

    old_length = strlen(object->valuestring);
    new_length = strlen(valuestring);

    if (new_length <= old_length)
    {
        if (object->valuestring == valuestring)
        {
            return NULL;
        }

        if ((char *)valuestring > object->valuestring &&
            (char *)valuestring < object->valuestring + old_length + 1)
        {
            return NULL;
        }

        if (object->valuestring > (char *)valuestring &&
            object->valuestring < (char *)valuestring + new_length + 1)
        {
            return NULL;
        }

        memcpy(object->valuestring, valuestring, new_length + 1);
        return object->valuestring;
    }

    copy = (char *)cJSON_strdup((const unsigned char *)valuestring, &global_hooks);
    if (copy == NULL)
    {
        return NULL;
    }

    cJSON_free(object->valuestring);
    object->valuestring = copy;

    return object->valuestring;
}
