static cJSON_bool print_number(const cJSON * const item, printbuffer * const output_buffer)
{
    unsigned char temporary[64];
    unsigned char *output = NULL;
    size_t length = 0;
    size_t i = 0;
    unsigned char decimal_point;
    double d = item->valuedouble;

    if (output_buffer == NULL)
    {
        return false;
    }

    if (isnan(d) || isinf(d))
    {
        length = 4;
        strcpy((char*)temporary, "null");
    }
    else
    {
        if (compare_double(d, (double)item->valueint))
        {
            length = (size_t)sprintf((char*)temporary, "%d", item->valueint);
        }
        else
        {
            length = (size_t)sprintf((char*)temporary, "%.15g", d);
            if (strtod((const char*)temporary, NULL) != d)
            {
                length = (size_t)sprintf((char*)temporary, "%.17g", d);
            }
        }
    }

    if (length >= sizeof(temporary))
    {
        return false;
    }

    output = ensure(output_buffer, length + 1);
    if (output == NULL)
    {
        return false;
    }

    decimal_point = get_decimal_point();
    for (i = 0; i < length; i++)
    {
        if (temporary[i] == decimal_point)
        {
            output[i] = '.';
        }
        else
        {
            output[i] = temporary[i];
        }
    }
    output[length] = '\0';

    output_buffer->offset += length;

    return true;
}
