static unsigned char utf16_literal_to_utf8(const unsigned char * const input_pointer, const unsigned char * const input_end, unsigned char **output_pointer)
{
    unsigned int code_point;
    unsigned int first;
    unsigned int second;
    const unsigned char *p = input_pointer;

    if ((size_t)(input_end - input_pointer) < 6) {
        return 0;
    }

    if (p[0] != '\\' || p[1] != 'u') {
        return 0;
    }

    first = parse_hex4(p + 2);

    if (first >= 0xDC00u && first <= 0xDFFFu) {
        return 0;
    }

    if (first >= 0xD800u && first <= 0xDBFFu) {
        if ((size_t)(input_end - input_pointer) < 12) {
            return 0;
        }
        if (p[6] != '\\' || p[7] != 'u') {
            return 0;
        }
        second = parse_hex4(p + 8);
        if (second < 0xDC00u || second > 0xDFFFu) {
            return 0;
        }
        code_point = 0x10000u + ((first - 0xD800u) << 10) + (second - 0xDC00u);
        p += 12;
    } else {
        code_point = first;
        p += 6;
    }

    if (code_point <= 0x7Fu) {
        (*output_pointer)[0] = (unsigned char)code_point;
        *output_pointer += 1;
    } else if (code_point <= 0x7FFu) {
        (*output_pointer)[0] = (unsigned char)(0xC0u | (code_point >> 6));
        (*output_pointer)[1] = (unsigned char)(0x80u | (code_point & 0x3Fu));
        *output_pointer += 2;
    } else if (code_point <= 0xFFFFu) {
        (*output_pointer)[0] = (unsigned char)(0xE0u | (code_point >> 12));
        (*output_pointer)[1] = (unsigned char)(0x80u | ((code_point >> 6) & 0x3Fu));
        (*output_pointer)[2] = (unsigned char)(0x80u | (code_point & 0x3Fu));
        *output_pointer += 3;
    } else {
        (*output_pointer)[0] = (unsigned char)(0xF0u | (code_point >> 18));
        (*output_pointer)[1] = (unsigned char)(0x80u | ((code_point >> 12) & 0x3Fu));
        (*output_pointer)[2] = (unsigned char)(0x80u | ((code_point >> 6) & 0x3Fu));
        (*output_pointer)[3] = (unsigned char)(0x80u | (code_point & 0x3Fu));
        *output_pointer += 4;
    }

    return (unsigned char)(p - input_pointer);
}
