static unsigned char *print(const cJSON * const item, cJSON_bool format, const internal_hooks * const hooks)
{
    printbuffer buffer;
    unsigned char *result = NULL;

    buffer.buffer = (unsigned char *)hooks->allocate(256);
    if (buffer.buffer == NULL)
    {
        return NULL;
    }

    buffer.length = 256;
    buffer.offset = 0;
    buffer.depth = 0;
    buffer.noalloc = 0;
    buffer.format = format;
    buffer.hooks = *hooks;

    if (!print_value(item, &buffer))
    {
        hooks->deallocate(buffer.buffer);
        return NULL;
    }

    if (hooks->reallocate != NULL)
    {
        result = (unsigned char *)hooks->reallocate(buffer.buffer, buffer.offset + 1);
        if (result == NULL)
        {
            hooks->deallocate(buffer.buffer);
            return NULL;
        }
    }
    else
    {
        result = (unsigned char *)hooks->allocate(buffer.offset + 1);
        if (result == NULL)
        {
            hooks->deallocate(buffer.buffer);
            return NULL;
        }
        memcpy(result, buffer.buffer, buffer.offset);
        hooks->deallocate(buffer.buffer);
    }

    result[buffer.offset] = '\0';
    return result;
}
