CJSON_PUBLIC(cJSON_bool) cJSON_PrintPreallocated(cJSON *item, char *buffer, const int length, const cJSON_bool format)
{
    printbuffer output_buffer;

    if (length < 0 || buffer == NULL)
    {
        return false;
    }

    output_buffer.buffer = (unsigned char *)buffer;
    output_buffer.length = (size_t)length;
    output_buffer.offset = 0;
    output_buffer.depth = 0;
    output_buffer.noalloc = true;
    output_buffer.format = format;
    output_buffer.hooks = global_hooks;

    if (!print_value(item, &output_buffer))
    {
        return false;
    }

    if (output_buffer.offset >= output_buffer.length)
    {
        return false;
    }

    output_buffer.buffer[output_buffer.offset] = '\0';

    return true;
}
