static cJSON_bool parse_value(cJSON * const item, parse_buffer * const input_buffer)
{
    if ((item == NULL) || (input_buffer == NULL) || (input_buffer->content == NULL) || (input_buffer->length == 0))
    {
        return false;
    }

    if (!can_access_at_index(input_buffer, 0))
    {
        return false;
    }

    if (strncmp((const char *)buffer_at_offset(input_buffer), "null", 4) == 0)
    {
        item->type = cJSON_NULL;
        input_buffer->offset += 4;
        return true;
    }

    if (strncmp((const char *)buffer_at_offset(input_buffer), "false", 5) == 0)
    {
        item->type = cJSON_False;
        input_buffer->offset += 5;
        return true;
    }

    if (strncmp((const char *)buffer_at_offset(input_buffer), "true", 4) == 0)
    {
        item->type = cJSON_True;
        item->valueint = 1;
        input_buffer->offset += 4;
        return true;
    }

    switch (buffer_at_offset(input_buffer)[0])
    {
        case '\"':
            return parse_string(item, input_buffer);
        case '-':
        case '0':
        case '1':
        case '2':
        case '3':
        case '4':
        case '5':
        case '6':
        case '7':
        case '8':
        case '9':
            return parse_number(item, input_buffer);
        case '[':
            return parse_array(item, input_buffer);
        case '{':
            return parse_object(item, input_buffer);
        default:
            return false;
    }
}
