static cJSON_bool print_array(const cJSON * const item, printbuffer * const output_buffer)
{
    const cJSON *current_child = NULL;

    if (output_buffer == NULL)
    {
        return false;
    }

    if (output_buffer->depth >= CJSON_NESTING_LIMIT)
    {
        return false;
    }

    if (ensure(output_buffer, 1) == NULL)
    {
        return false;
    }
    output_buffer->buffer[output_buffer->offset] = '[';
    output_buffer->offset++;
    output_buffer->depth++;

    current_child = item->child;
    while (current_child != NULL)
    {
        if (print_value(current_child, output_buffer) == false)
        {
            return false;
        }
        if (current_child->next != NULL)
        {
            if (ensure(output_buffer, output_buffer->format ? 2 : 1) == NULL)
            {
                return false;
            }
            output_buffer->buffer[output_buffer->offset] = ',';
            output_buffer->offset++;
            if (output_buffer->format)
            {
                output_buffer->buffer[output_buffer->offset] = ' ';
                output_buffer->offset++;
            }
        }
        current_child = current_child->next;
    }

    if (ensure(output_buffer, 2) == NULL)
    {
        return false;
    }
    output_buffer->buffer[output_buffer->offset] = ']';
    output_buffer->offset++;
    output_buffer->buffer[output_buffer->offset] = '\0';
    output_buffer->offset++;
    output_buffer->depth--;

    return true;
}
