static cJSON_bool parse_object(cJSON * const item, parse_buffer * const input_buffer)
{
    cJSON *head = NULL;
    cJSON *tail = NULL;
    cJSON *current_item = NULL;

    if (input_buffer == NULL || input_buffer->content == NULL)
    {
        return false;
    }

    if (input_buffer->depth >= CJSON_NESTING_LIMIT)
    {
        return false;
    }
    input_buffer->depth++;

    if (buffer_skip_whitespace(input_buffer) == NULL)
    {
        input_buffer->depth--;
        return false;
    }

    if (cannot_access_at_index(input_buffer, 0) || buffer_at_offset(input_buffer)[0] != '{')
    {
        input_buffer->depth--;
        return false;
    }

    input_buffer->offset++;
    if (buffer_skip_whitespace(input_buffer) == NULL)
    {
        input_buffer->depth--;
        return false;
    }

    if (can_access_at_index(input_buffer, 0) && buffer_at_offset(input_buffer)[0] == '}')
    {
        input_buffer->offset++;
        input_buffer->depth--;
        item->type = cJSON_Object;
        item->child = NULL;
        return true;
    }

    for (;;)
    {
        current_item = cJSON_New_Item(&(input_buffer->hooks));
        if (current_item == NULL)
        {
            goto fail;
        }

        if (!parse_string(current_item, input_buffer))
        {
            cJSON_Delete(current_item);
            goto fail;
        }

        if (buffer_skip_whitespace(input_buffer) == NULL)
        {
            cJSON_Delete(current_item);
            goto fail;
        }

        if (cannot_access_at_index(input_buffer, 0) || buffer_at_offset(input_buffer)[0] != ':')
        {
            cJSON_Delete(current_item);
            goto fail;
        }
        input_buffer->offset++;

        if (buffer_skip_whitespace(input_buffer) == NULL)
        {
            cJSON_Delete(current_item);
            goto fail;
        }

        if (!parse_value(current_item, input_buffer))
        {
            cJSON_Delete(current_item);
            goto fail;
        }

        if (head == NULL)
        {
            head = current_item;
            tail = current_item;
        }
        else
        {
            tail->next = current_item;
            current_item->prev = tail;
            tail = current_item;
        }

        if (buffer_skip_whitespace(input_buffer) == NULL)
        {
            goto fail;
        }

        if (cannot_access_at_index(input_buffer, 0))
        {
            goto fail;
        }

        if (buffer_at_offset(input_buffer)[0] == ',')
        {
            input_buffer->offset++;
            if (buffer_skip_whitespace(input_buffer) == NULL)
            {
                goto fail;
            }
            if (cannot_access_at_index(input_buffer, 0) || buffer_at_offset(input_buffer)[0] == '}')
            {
                goto fail;
            }
            continue;
        }

        if (buffer_at_offset(input_buffer)[0] == '}')
        {
            input_buffer->offset++;
            break;
        }

        goto fail;
    }

    if (tail != NULL)
    {
        tail->next = head;
        head->prev = tail;
    }

    input_buffer->depth--;
    item->type = cJSON_Object;
    item->child = head;
    return true;

fail:
    if (head != NULL)
    {
        cJSON_Delete(head);
    }
    input_buffer->depth--;
    return false;
}
