static cJSON_bool print_object(const cJSON * const item, printbuffer * const output_buffer)
{
    const cJSON *current_child = NULL;
    size_t depth = 0;

    if (output_buffer == NULL)
    {
        return false;
    }

    if (output_buffer->depth >= CJSON_NESTING_LIMIT)
    {
        return false;
    }

    if (ensure(output_buffer, 1) == NULL)
    {
        return false;
    }
    output_buffer->buffer[output_buffer->offset++] = '{';
    output_buffer->depth++;

    if (output_buffer->format)
    {
        if (ensure(output_buffer, 1) == NULL)
        {
            return false;
        }
        output_buffer->buffer[output_buffer->offset++] = '\n';
    }

    current_child = item->child;

    while (current_child != NULL)
    {
        size_t i = 0;

        if (output_buffer->format)
        {
            for (i = 0; i < output_buffer->depth; i++)
            {
                if (ensure(output_buffer, 1) == NULL)
                {
                    return false;
                }
                output_buffer->buffer[output_buffer->offset++] = '\t';
            }
        }

        if (!print_string_ptr((const unsigned char *)current_child->string, output_buffer))
        {
            return false;
        }

        if (ensure(output_buffer, 1) == NULL)
        {
            return false;
        }
        output_buffer->buffer[output_buffer->offset++] = ':';

        if (output_buffer->format)
        {
            if (ensure(output_buffer, 1) == NULL)
            {
                return false;
            }
            output_buffer->buffer[output_buffer->offset++] = '\t';
        }

        if (!print_value(current_child, output_buffer))
        {
            return false;
        }

        if (current_child->next != NULL)
        {
            if (ensure(output_buffer, 1) == NULL)
            {
                return false;
            }
            output_buffer->buffer[output_buffer->offset++] = ',';
        }

        if (output_buffer->format)
        {
            if (ensure(output_buffer, 1) == NULL)
            {
                return false;
            }
            output_buffer->buffer[output_buffer->offset++] = '\n';
        }

        current_child = current_child->next;
    }

    if (output_buffer->format)
    {
        size_t i = 0;
        depth = output_buffer->depth - 1;
        for (i = 0; i < depth; i++)
        {
            if (ensure(output_buffer, 1) == NULL)
            {
                return false;
            }
            output_buffer->buffer[output_buffer->offset++] = '\t';
        }
    }

    if (ensure(output_buffer, 1) == NULL)
    {
        return false;
    }
    output_buffer->buffer[output_buffer->offset++] = '}';
    output_buffer->depth--;

    return true;
}
