static cJSON_bool add_item_to_array(cJSON *array, cJSON *item)
{
    if (array == NULL || item == NULL || array == item)
    {
        return false;
    }

    if (array->child == NULL)
    {
        array->child = item;
        item->prev = item;
        item->next = NULL;
    }
    else
    {
        cJSON *last = array->child->prev;
        suffix_object(last, item);
        array->child->prev = item;
    }

    return true;
}
