static void minify_string(char **input, char **output)
{
    char *src = *input;
    char *dst = *output;

    *dst++ = *src++;

    while (*src != '\0') {
        if (*src == '"') {
            *dst++ = *src++;
            break;
        }
        if (*src == '\\' && *(src + 1) == '"') {
            src++;
            *dst++ = *src++;
        } else {
            *dst++ = *src++;
        }
    }

    *input = src;
    *output = dst;
}
