static int jsmn_parse_string(jsmn_parser *parser, const char *js, const size_t len, jsmntok_t *tokens, const size_t num_tokens)
{
    unsigned int start = parser->pos;
    unsigned int i = start + 1;

    while (i < len && js[i] != '\0') {
        if (js[i] == '"') {
            if (tokens != NULL) {
                jsmntok_t *token = jsmn_alloc_token(parser, tokens, num_tokens);
                if (token == NULL) {
                    parser->pos = start;
                    return JSMN_ERROR_NOMEM;
                }
                jsmn_fill_token(token, JSMN_STRING, (int)start + 1, (int)i);
            }
            parser->pos = i + 1;
            return 0;
        }

        if (js[i] == '\\') {
            i++;
            if (i >= len || js[i] == '\0') {
                parser->pos = start;
                return JSMN_ERROR_PART;
            }

            switch (js[i]) {
                case '"':
                case '/':
                case '\\':
                case 'b':
                case 'f':
                case 'r':
                case 'n':
                case 't':
                    i++;
                    break;
                case 'u': {
                    int j;
                    for (j = 0; j < 4; j++) {
                        i++;
                        if (i >= len || js[i] == '\0') {
                            parser->pos = start;
                            return JSMN_ERROR_PART;
                        }
                        if (!((js[i] >= '0' && js[i] <= '9') ||
                              (js[i] >= 'a' && js[i] <= 'f') ||
                              (js[i] >= 'A' && js[i] <= 'F'))) {
                            parser->pos = start;
                            return JSMN_ERROR_INVAL;
                        }
                    }
                    i++;
                    break;
                }
                default:
                    parser->pos = start;
                    return JSMN_ERROR_INVAL;
            }
        } else {
            i++;
        }
    }

    parser->pos = start;
    return JSMN_ERROR_PART;
}
