static void mpc_input_mark(mpc_input_t *i)
{
  if (!i->backtrack) {
    return;
  }

  i->marks_num++;

  if (i->marks_num > i->marks_slots) {
    int new_capacity = i->marks_num + i->marks_num / 2;
    i->marks = (mpc_state_t *)realloc(i->marks, sizeof(mpc_state_t) * new_capacity);
    i->lasts = (char *)realloc(i->lasts, sizeof(char) * new_capacity);
    i->marks_slots = new_capacity;
  }

  i->marks[i->marks_num - 1].pos = i->state.pos;
  i->marks[i->marks_num - 1].row = i->state.row;
  i->marks[i->marks_num - 1].col = i->state.col;
  i->marks[i->marks_num - 1].term = i->state.term;
  i->lasts[i->marks_num - 1] = i->last;

  if (i->type == MPC_INPUT_PIPE && i->marks_num == 1) {
    i->buffer = (char *)malloc(1);
    i->buffer[0] = '\0';
  }
}
