static void mpc_input_unmark(mpc_input_t *i)
{
    int new_num;
    int new_slots;
    mpc_state_t *new_marks;
    char *new_lasts;

    if (i->marks_num < 1) {
        return;
    }

    i->marks_num--;

    if (i->marks_slots > MPC_INPUT_MARKS_MIN &&
        i->marks_slots > (i->marks_num * 3) / 2) {
        new_slots = i->marks_num;
        if (new_slots < MPC_INPUT_MARKS_MIN) {
            new_slots = MPC_INPUT_MARKS_MIN;
        }

        new_marks = (mpc_state_t *)realloc(i->marks, (size_t)new_slots * sizeof(mpc_state_t));
        if (new_marks != NULL) {
            i->marks = new_marks;
        }

        new_lasts = (char *)realloc(i->lasts, (size_t)new_slots * sizeof(char));
        if (new_lasts != NULL) {
            i->lasts = new_lasts;
        }

        i->marks_slots = new_slots;
    }

    if (i->type == MPC_INPUT_PIPE && i->marks_num == 0 && i->buffer != NULL) {
        size_t len = strlen(i->buffer);
        while (len > 0) {
            len--;
            ungetc((unsigned char)i->buffer[len], i->file);
        }
        free(i->buffer);
        i->buffer = NULL;
    }
}
