```c
static mpc_err_t *mpc_err_or(mpc_input_t *i, mpc_err_t** x, int n)
{
    mpc_err_t *e;
    mpc_err_t *last = NULL;
    long max_pos = -1;
    int j;

    for (j = 0; j < n; j++) {
        if (x[j] != NULL) {
            last = x[j];
        }
    }

    if (last == NULL) {
        return NULL;
    }

    e = (mpc_err_t *)mpc_malloc(i, sizeof(mpc_err_t));
    e->state = mpc_state_invalid();
    e->expected_num = 0;
    e->filename = (char *)mpc_malloc(i, strlen(last->filename) + 1);
    strcpy(e->filename, last->filename);
    e->failure = NULL;
    e->expected = NULL;
    e->received = '\0';

    for (j = 0; j < n; j++) {
        if (x[j] != NULL && x[j]->state.pos > max_pos) {
            max_pos = x[j]->state.pos;
        }
    }

    e->state = x[0]->state;
    for (j = 0; j < n; j++) {
        if (x[j] != NULL && x[j]->state.pos == max_pos) {
            e->state = x[j]->state;
            break;
        }
    }

    for (j = 0; j < n; j++) {
        if (x[j] != NULL && x[j]->state.pos == max_pos) {
            if (x[j]->failure != NULL) {
                e->failure = (char *)mpc_malloc(i, strlen(x[j]->failure) + 1);
                strcpy(e->failure, x[j]->failure);
                break;
            }
        }
    }

    if (e->failure == NULL) {
        for (j = 0; j < n; j++) {
            if (x[j] != NULL && x[j]->state.pos == max_pos) {
                int k;
                e->received = x[j]->received;
                for (k = 0; k < x[j]->expected_num; k++) {
                    if (!mpc_err_contains_expected(i, e, x[j]->expected[k])) {
                        mpc_err_add_expected(i, e, x[j]->expected[k]);
                    }
                }
            }
        }
    }

    for (j = 0; j < n; j++) {
        if (x[j] != NULL) {
            mpc_err_delete_internal(i, x[j]);
        }
    }

    return e;
}
