int mpc_parse_input(mpc_input_t *i, mpc_parser_t *p, mpc_result_t *r)
{
    mpc_err_t *e;
    mpc_result_t result;
    int success;

    e = mpc_err_fail(i, "Unknown Error");
    e->state = mpc_state_invalid();

    success = mpc_parse_run(i, p, &result, &e, 0);

    if (success) {
        mpc_err_delete_internal(i, e);
        r->output = mpc_export(i, result.output);
        return 1;
    } else {
        mpc_err_t *merged = mpc_err_merge(i, e, result.error);
        r->error = mpc_err_export(i, merged);
        return 0;
    }
}
