static mpc_val_t *mpcf_re_range(mpc_val_t *x)
{
    char *input = (char *)x;
    char *p;
    int complement = 0;
    size_t len;
    size_t cap;
    char *set;
    size_t set_len = 0;
    mpc_parser_t *parser;

    if (input == NULL || *input == '\0') {
        free(input);
        return mpc_fail("Invalid Regex Range Expression");
    }

    p = input;
    if (*p == '^') {
        complement = 1;
        p++;
        if (*p == '\0') {
            free(input);
            return mpc_fail("Invalid Regex Range Expression");
        }
    }

    len = strlen(p);
    cap = len * 2 + 1;
    set = (char *)malloc(cap);
    if (set == NULL) {
        free(input);
        return mpc_fail("Invalid Regex Range Expression");
    }

    while (*p != '\0') {
        if (*p == '\\') {
            const char *translated;
            p++;
            if (*p == '\0') {
                break;
            }
            translated = mpc_re_range_escape_char(*p);
            if (translated != NULL) {
                size_t tlen = strlen(translated);
                if (set_len + tlen + 1 > cap) {
                    cap = (set_len + tlen + 1) * 2;
                    set = (char *)realloc(set, cap);
                    if (set == NULL) {
                        free(input);
                        return mpc_fail("Invalid Regex Range Expression");
                    }
                }
                memcpy(set + set_len, translated, tlen);
                set_len += tlen;
            } else {
                if (set_len + 2 > cap) {
                    cap = (set_len + 2) * 2;
                    set = (char *)realloc(set, cap);
                    if (set == NULL) {
                        free(input);
                        return mpc_fail("Invalid Regex Range Expression");
                    }
                }
                set[set_len++] = *p;
            }
            p++;
        } else if (*p == '-') {
            if (set_len == 0 || *(p + 1) == '\0') {
                if (set_len + 2 > cap) {
                    cap = (set_len + 2) * 2;
                    set = (char *)realloc(set, cap);
                    if (set == NULL) {
                        free(input);
                        return mpc_fail("Invalid Regex Range Expression");
                    }
                }
                set[set_len++] = '-';
                p++;
            } else {
                char start = set[set_len - 1];
                char end;
                p++;
                if (*p == '\\') {
                    const char *translated;
                    p++;
                    if (*p == '\0') {
                        break;
                    }
                    translated = mpc_re_range_escape_char(*p);
                    if (translated != NULL && strlen(translated) == 1) {
                        end = translated[0];
                    } else {
                        end = *p;
                    }
                    p++;
                } else if (*p != '\0') {
                    end = *p;
                    p++;
                } else {
                    break;
                }

                if (start <= end) {
                    size_t i;
                    size_t count = (size_t)(end - start) + 1;
                    if (set_len + count + 1 > cap) {
                        cap = (set_len + count + 1) * 2;
                        set = (char *)realloc(set, cap);
                        if (set == NULL) {
                            free(input);
                            return mpc_fail("Invalid Regex Range Expression");
                        }
                    }
                    for (i = 0; i < count; i++) {
                        set[set_len++] = (char)(start + i);
                    }
                } else {
                    if (set_len + 2 > cap) {
                        cap = (set_len + 2) * 2;
                        set = (char *)realloc(set, cap);
                        if (set == NULL) {
                            free(input);
                            return mpc_fail("Invalid Regex Range Expression");
                        }
                    }
                    set[set_len++] = '-';
                    set[set_len++] = end;
                }
            }
        } else {
            if (set_len + 2 > cap) {
                cap = (set_len + 2) * 2;
                set = (char *)realloc(set, cap);
                if (set == NULL) {
                    free(input);
                    return mpc_fail("Invalid Regex Range Expression");
                }
            }
            set[set_len++] = *p;
            p++;
        }
    }

    set[set_len] = '\0';

    if (complement) {
        parser = mpc_noneof(set);
    } else {
        parser = mpc_oneof(set);
    }

    free(set);
    free(input);
    return parser;
}
