mpc_parser_t *mpc_re_mode(const char *re, int mode) {
  const char *p = re;
  mpc_parser_t *result = NULL;
  mpc_parser_t *elem = NULL;
  mpc_parser_t *seq = NULL;
  mpc_parser_t *alt = NULL;
  mpc_parser_t *tmp = NULL;
  mpc_parser_t *rep = NULL;
  mpc_parser_t *cls = NULL;
  mpc_parser_t *lit = NULL;
  mpc_parser_t *esc = NULL;
  mpc_parser_t *num = NULL;
  mpc_parser_t *whole = NULL;
  char buf[2];
  char err[128];
  int n = 0;
  int m = 0;
  int i = 0;
  int valid = 1;
  int in_class = 0;
  int class_start = 0;
  int class_neg = 0;
  int class_count = 0;
  char class_chars[256];
  char c;

  (void)mode;

  if (re == NULL) {
    return mpc_failf("Invalid Regex: null pattern");
  }

  alt = mpc_new("alt");
  seq = mpc_new("seq");

  while (*p != '\0' && valid) {
    c = *p;

    if (c == '(') {
      int depth = 1;
      const char *q = p + 1;
      while (*q != '\0' && depth > 0) {
        if (*q == '\\' && *(q+1) != '\0') {
          q += 2;
        } else if (*q == '(') {
          depth++;
          q++;
        } else if (*q == ')') {
          depth--;
          if (depth > 0) q++;
        } else {
          q++;
        }
      }
      if (depth != 0) {
        sprintf(err, "Invalid Regex: unmatched '('");
        valid = 0;
        break;
      }
      {
        char *sub = (char*)malloc((size_t)(q - p));
        if (sub == NULL) {
          valid = 0;
          sprintf(err, "Invalid Regex: memory allocation failed");
          break;
        }
        memcpy(sub, p + 1, (size_t)(q - p - 1));
        sub[q - p - 1] = '\0';
        elem = mpc_re_mode(sub, mode);
        free(sub);
        if (elem == NULL) {
          valid = 0;
          sprintf(err, "Invalid Regex: subexpression failed");
          break;
        }
      }
      p = q;
    } else if (c == '[') {
      in_class = 1;
      class_start = 1;
      class_neg = 0;
      class_count = 0;
      p++;
      if (*p == '^') {
        class_neg = 1;
        p++;
      }
      while (*p != '\0' && *p != ']') {
        if (*p == '\\' && *(p+1) != '\0') {
          p++;
          class_chars[class_count++] = *p;
          p++;
        } else {
          class_chars[class_count++] = *p;
          p++;
        }
      }
      if (*p != ']') {
        sprintf(err, "Invalid Regex: unmatched '['");
        valid = 0;
        break;
      }
      p++;
      if (class_count == 0) {
        sprintf(err, "Invalid Regex: empty character class");
        valid = 0;
        break;
      }
      {
        char *set = (char*)malloc((size_t)class_count + 1);
        if (set == NULL) {
          valid = 0;
          sprintf(err, "Invalid Regex: memory allocation failed");
          break;
        }
        memcpy(set, class_chars, (size_t)class_count);
        set[class_count] = '\0';
        if (class_neg) {
          elem = mpc_noneof(set);
        } else {
          int j;
          mpc_parser_t *first = NULL;
          for (j = 0; j < class_count; j++) {
            if (j == 0) {
              first = mpc_char(set[j]);
            } else {
              first = mpc_or(2, first, mpc_char(set[j]));
            }
          }
          elem = first;
        }
        free(set);
      }
    } else if (c == '.') {
      elem = mpc_escape();
      p++;
    } else if (c == '\\') {
      if (*(p+1) == '\0') {
        sprintf(err, "Invalid Regex: trailing escape");
        valid = 0;
        break;
      }
      p++;
      buf[0] = *p;
      buf[1] = '\0';
      elem = mpc_char(buf[0]);
      p++;
    } else if (c == '|') {
      if (seq != NULL) {
        mpc_define(alt, seq);
        seq = mpc_new("seq");
      }
      p++;
      continue;
    } else if (c == ')') {
      sprintf(err, "Invalid Regex: unmatched ')'");
      valid = 0;
      break;
    } else if (c == '*') {
      if (seq == NULL || elem == NULL) {
        sprintf(err, "Invalid Regex: '*' with no preceding element");
        valid = 0;
        break;
      }
      rep = mpc_many(mpcf_strfold, elem);
      elem = rep;
      p++;
      continue;
    } else if (c == '+') {
      if (seq == NULL || elem == NULL) {
        sprintf(err, "Invalid Regex: '+' with no preceding element");
        valid = 0;
        break;
      }
      rep = mpc_many(mpcf_strfold, elem);
      elem = mpc_and(2, mpcf_strfold, elem, rep);
      p++;
      continue;
    } else if (c == '?') {
      if (seq == NULL || elem == NULL) {
        sprintf(err, "Invalid Regex: '?' with no preceding element");
        valid = 0;
        break;
      }
      elem = mpc_maybe(elem);
      p++;
      continue;
    } else if (c == '{') {
      const char *q = p + 1;
      n = 0;
      m = -1;
      if (*q == '\0') {
        sprintf(err, "Invalid Regex: unmatched '{'");
        valid = 0;
        break;
      }
      while (*q >= '0' && *q <= '9') {
        n = n * 10 + (*q - '0');
        q++;
      }
      if (*q == '}') {
        m = n;
        q++;
      } else if (*q == ',') {
        q++;
        if (*q == '}') {
          m = -1;
          q++;
        } else {
          m = 0;
          while (*q >= '0' && *q <= '9') {
            m = m * 10 + (*q - '0');
            q++;
          }
          if (*q != '}') {
            sprintf(err, "Invalid Regex: malformed repetition");
            valid = 0;
            break;
          }
          q++;
        }
      } else {
        sprintf(err, "Invalid Regex: malformed repetition");
        valid = 0;
        break;
      }
      if (elem == NULL) {
        sprintf(err, "Invalid Regex: repetition with no preceding element");
        valid = 0;
        break;
      }
      if (m == -1) {
        rep = mpc_many(mpcf_strfold, elem);
        if (n > 0) {
          mpc_parser_t *first = NULL;
          for (i = 0; i < n; i++) {
            if (i == 0) {
              first = elem;
            } else {
              first = mpc_and(2, mpcf_strfold, first, elem);
            }
          }
          elem = mpc_and(2, mpcf_strfold, first, rep);
        } else {
          elem = rep;
        }
      } else {
        if (m < n) {
          sprintf(err, "Invalid Regex: repetition count out of order");
          valid = 0;
          break;
        }
        if (m == 0) {
          elem = mpc_pass();
        } else {
          mpc_parser_t *first = NULL;
          for (i = 0; i < n; i++) {
            if (i == 0) {
              first = elem;
            } else {
              first = mpc_and(2, mpcf_strfold, first, elem);
            }
          }
          if (n == 0) {
            first = mpc_pass();
          }
          for (i = n; i < m; i++) {
            first = mpc_and(2, mpcf_strfold, first, mpc_maybe(elem));
          }
          elem = first;
        }
      }
      p = q;
      continue;
    } else {
      buf[0] = c;
      buf[1] = '\0';
      elem = mpc_char(c);
      p++;
    }

    if (elem != NULL) {
      if (seq == NULL) {
        seq = mpc_new("seq");
      }
      mpc_define(seq, elem);
      elem = NULL;
    }
  }

  if (!valid) {
    if (alt != NULL) mpc_delete(alt);
    if (seq != NULL) mpc_delete(seq);
    return mpc_failf("%s", err);
  }

  if (seq != NULL) {
    mpc_define(alt, seq);
  }

  if (alt == NULL) {
    alt = mpc_pass();
  }

  whole = mpc_whole(alt, (mpc_dtor_t)free);
  mpc_optimise(whole);
  return whole;
}
