mpc_ast_t *mpc_ast_add_tag(mpc_ast_t *a, const char *t)
{
    char *new_tag;
    size_t t_len;
    size_t old_len;

    if (a == NULL) {
        return NULL;
    }

    t_len = strlen(t);
    old_len = (a->tag != NULL) ? strlen(a->tag) : 0;

    new_tag = (char *)malloc(t_len + 1 + old_len + 1);

    memcpy(new_tag, t, t_len);
    new_tag[t_len] = '|';
    if (a->tag != NULL) {
        memcpy(new_tag + t_len + 1, a->tag, old_len);
    }
    new_tag[t_len + 1 + old_len] = '\0';

    free(a->tag);
    a->tag = new_tag;

    return a;
}
