mpc_ast_t *mpc_ast_add_root_tag(mpc_ast_t *a, const char *t)
{
    size_t prefix_len;
    size_t tag_len;
    char *new_tag;

    if (a == NULL) {
        return NULL;
    }

    prefix_len = strlen(t) - 1;
    tag_len = strlen(a->tag);

    new_tag = (char *)realloc(a->tag, prefix_len + tag_len + 1);
    if (new_tag == NULL) {
        return NULL;
    }

    memmove(new_tag + prefix_len, new_tag, tag_len + 1);
    memcpy(new_tag, t, prefix_len);

    a->tag = new_tag;

    return a;
}
