static mpc_val_t *mpcaf_fold_regex(int n, mpc_val_t **xs)
{
    int mode = MPC_RE_DEFAULT;
    char *re;
    char *flags;
    mpca_grammar_st_t *gs;
    mpc_parser_t *p;
    const char *s;

    (void)n;

    re = (char *)xs[0];
    flags = (char *)xs[1];
    gs = (mpca_grammar_st_t *)xs[2];

    for (s = flags; *s != '\0'; s++) {
        if (*s == 'm') {
            mode |= MPC_RE_M;
        } else if (*s == 's') {
            mode |= MPC_RE_S;
        }
    }

    re = (char *)mpcf_unescape_regex(re);
    p = mpc_re_mode(re, mode);
    free(re);
    free(flags);

    if (!(gs->flags & MPCA_LANG_WHITESPACE_SENSITIVE)) {
        p = mpc_tok(p);
    }

    p = mpc_apply(p, mpcf_str_ast);
    p = mpca_tag(p, "regex");
    return mpca_state(p);
}
