static mpc_parser_t *mpca_grammar_find_parser(char *x, mpca_grammar_st_t *st)
{
    if (is_number(x)) {
        int pos = atoi(x);
        mpc_parser_t *p;
        while (st->parsers_num <= pos) {
            p = va_arg(*(st->va), mpc_parser_t *);
            st->parsers = (mpc_parser_t **)realloc(st->parsers, sizeof(mpc_parser_t *) * (st->parsers_num + 1));
            st->parsers[st->parsers_num] = p;
            st->parsers_num++;
            if (p == NULL) {
                return mpc_failf("Parser at position %d requested but only %d supplied", pos, st->parsers_num - 1);
            }
        }
        return st->parsers[pos];
    } else {
        int i;
        for (i = 0; i < st->parsers_num; i++) {
            if (st->parsers[i] == NULL) {
                return mpc_failf("Unknown Parser '%s'", x);
            }
            if (st->parsers[i]->name != NULL && strcmp(st->parsers[i]->name, x) == 0) {
                return st->parsers[i];
            }
        }
        while (1) {
            mpc_parser_t *p = va_arg(*(st->va), mpc_parser_t *);
            st->parsers = (mpc_parser_t **)realloc(st->parsers, sizeof(mpc_parser_t *) * (st->parsers_num + 1));
            st->parsers[st->parsers_num] = p;
            st->parsers_num++;
            if (p == NULL || p->name == NULL) {
                return mpc_failf("Unknown Parser '%s'", x);
            }
            if (strcmp(p->name, x) == 0) {
                return p;
            }
        }
    }
}
