mpc_parser_t *mpca_grammar_st(const char *grammar, mpca_grammar_st_t *st)
{
    mpc_parser_t *Grammar, *Rule, *Term, *Factor, *Base, *Regex, *String, *Char, *Ident, *Number, *Paren, *Spacing;
    mpc_parser_t *result;
    mpc_result_t r;
    int predictive;

    predictive = (st->flags & MPCA_LANG_PREDICTIVE) != 0;

    Grammar = mpc_new("grammar");
    Rule = mpc_new("rule");
    Term = mpc_new("term");
    Factor = mpc_new("factor");
    Base = mpc_new("base");
    Regex = mpc_new("regex");
    String = mpc_new("string");
    Char = mpc_new("char");
    Ident = mpc_new("ident");
    Number = mpc_new("number");
    Paren = mpc_new("paren");
    Spacing = mpc_new("spacing");

    mpc_define(Spacing, mpc_many(mpcf_strfold, mpc_or(2, mpc_oneof(" \t\n\r"), mpc_and(2, mpcf_snd_free, mpc_sym("#"), mpc_many(mpcf_strfold, mpc_oneof("\n")), free))));

    mpc_define(Ident, mpc_and(2, mpcf_strfold,
        mpc_or(2, mpc_oneof("_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"), mpc_oneof("\\")),
        mpc_many(mpcf_strfold, mpc_or(2, mpc_oneof("_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"), mpc_oneof("\\"))),
        free));

    mpc_define(Number, mpc_and(2, mpcf_strfold, mpc_many1(mpcf_strfold, mpc_digits()), mpc_maybe(mpc_and(2, mpcf_strfold, mpc_sym("."), mpc_many1(mpcf_strfold, mpc_digits()), free)), free));

    mpc_define(String, mpc_apply_to(mpc_tok(mpc_string_lit()), mpcaf_grammar_string, (void*)st));

    mpc_define(Char, mpc_apply_to(mpc_tok(mpc_char_lit()), mpcaf_grammar_char, (void*)st));

    mpc_define(Regex, mpc_apply_to(mpc_tok(mpc_regex_lit()), mpcaf_fold_regex, (void*)st));

    mpc_define(Base, mpc_or(5,
        mpc_apply_to(mpc_tok(mpc_ident()), mpcaf_grammar_id, (void*)st),
        String,
        Char,
        Regex,
        mpc_tok_parens(mpc_apply_to(mpc_tok(mpc_ident()), mpcaf_grammar_id, (void*)st), free)
    ));

    mpc_define(Factor, mpc_or(6,
        mpc_and(2, mpcf_snd_free, Base, mpc_sym("*"), free),
        mpc_and(2, mpcf_snd_free, Base, mpc_sym("+"), free),
        mpc_and(2, mpcf_snd_free, Base, mpc_sym("?"), free),
        mpc_and(2, mpcf_snd_free, Base, mpc_sym("!"), free),
        mpc_and(3, mpcf_snd_free, Base, mpc_sym("{"), mpc_tok(mpc_int()), mpc_sym("}"), free),
        Base
    ));

    mpc_define(Term, mpc_many1(mpcf_strfold, Factor));

    mpc_define(Rule, mpc_and(3, mpcf_snd_free,
        mpc_tok(mpc_ident()),
        mpc_sym(":"),
        mpc_or(2, Term, mpc_sym("|")),
        mpc_sym(";"),
        free
