static JSON_Status json_object_init(JSON_Object *object, size_t capacity)
{
    object->cells = NULL;
    object->hashes = NULL;
    object->names = NULL;
    object->values = NULL;
    object->cell_ixs = NULL;
    object->count = 0;
    object->item_capacity = 0;
    object->cell_capacity = 0;

    if (capacity == 0) {
        return JSONSuccess;
    }

    object->cell_capacity = capacity;
    object->item_capacity = (capacity * 7) / 10;

    object->cells = (size_t *)parson_malloc(capacity * sizeof(size_t));
    if (object->cells == NULL) {
        return JSONFailure;
    }

    object->names = (char **)parson_malloc(object->item_capacity * sizeof(char *));
    if (object->names == NULL) {
        parson_free(object->cells);
        object->cells = NULL;
        return JSONFailure;
    }

    object->values = (JSON_Value **)parson_malloc(object->item_capacity * sizeof(JSON_Value *));
    if (object->values == NULL) {
        parson_free(object->cells);
        parson_free(object->names);
        object->cells = NULL;
        object->names = NULL;
        return JSONFailure;
    }

    object->cell_ixs = (size_t *)parson_malloc(object->item_capacity * sizeof(size_t));
    if (object->cell_ixs == NULL) {
        parson_free(object->cells);
        parson_free(object->names);
        parson_free(object->values);
        object->cells = NULL;
        object->names = NULL;
        object->values = NULL;
        return JSONFailure;
    }

    object->hashes = (unsigned long *)parson_malloc(object->item_capacity * sizeof(unsigned long));
    if (object->hashes == NULL) {
        parson_free(object->cells);
        parson_free(object->names);
        parson_free(object->values);
        parson_free(object->cell_ixs);
        object->cells = NULL;
        object->names = NULL;
        object->values = NULL;
        object->cell_ixs = NULL;
        return JSONFailure;
    }

    {
        size_t i;
        for (i = 0; i < capacity; i++) {
            object->cells[i] = OBJECT_INVALID_IX;
        }
    }

    return JSONSuccess;
}
