static size_t json_object_get_cell_ix(const JSON_Object *object, const char *key, size_t key_len, unsigned long hash, parson_bool_t *out_found)
{
    size_t ix;
    size_t probe_count;
    size_t cell_capacity = object->cell_capacity;

    *out_found = PARSON_FALSE;

    ix = (size_t)hash & (cell_capacity - 1);

    for (probe_count = 0; probe_count < cell_capacity; probe_count++) {
        size_t cell_ix = (ix + probe_count) & (cell_capacity - 1);

        if (object->cells[cell_ix] == OBJECT_INVALID_IX) {
            return cell_ix;
        }

        if (object->hashes[cell_ix] == hash) {
            size_t stored_ix = object->cells[cell_ix];
            if (object->names[stored_ix] != NULL &&
                object->names[stored_ix][0] != '\0' &&
                strlen(object->names[stored_ix]) == key_len &&
                memcmp(object->names[stored_ix], key, key_len) == 0) {
                *out_found = PARSON_TRUE;
                return cell_ix;
            }
        }
    }

    return OBJECT_INVALID_IX;
}
