```c
static JSON_Value * parse_array_value(const char **string, size_t nesting)
{
    JSON_Value *array_value;
    JSON_Array *array;
    JSON_Value *element;
    int done = 0;

    array_value = json_value_init_array();
    if (array_value == NULL) {
        return NULL;
    }

    if (**string != '[') {
        json_value_free(array_value);
        return NULL;
    }
    SKIP_CHAR(string);
    SKIP_WHITESPACES(string);

    if (**string == ']') {
        SKIP_CHAR(string);
        return array_value;
    }

    array = json_value_get_array(array_value);

    while (!done) {
        element = parse_value(string, nesting);
        if (element == NULL) {
            json_value_free(array_value);
            return NULL;
        }

        if (json_array_add(array, element) != JSONSuccess) {
            json_value_free(element);
            json_value_free(array_value);
            return NULL;
        }

        SKIP_WHITESPACES(string);

        if (**string != ',') {
            done = 1;
        } else {
            SKIP_CHAR(string);
            SKIP_WHITESPACES(string);
            if (**string == ']') {
                done = 1;
            }
        }
    }

    SKIP_WHITESPACES(string);

    if (**string != ']') {
        json_value_free(array_value);
        return NULL;
    }

    if (json_array_resize(array, array->count) != JSONSuccess) {
        json_value_free(array_value);
        return NULL;
    }

    SKIP_CHAR(string);
    return array_value;
}
