```c
JSON_Value * json_value_deep_copy(const JSON_Value *value)
{
    JSON_Value_Type type;
    JSON_Value *copy = NULL;

    if (value == NULL) {
        return NULL;
    }

    type = json_value_get_type(value);

    if (type == JSONError) {
        return NULL;
    }

    switch (type) {
        case JSONNull:
            copy = json_value_init_null();
            break;
        case JSONNumber:
            copy = json_value_init_number(json_value_get_number(value));
            break;
        case JSONBoolean:
            copy = json_value_init_boolean(json_value_get_boolean(value));
            break;
        case JSONString: {
            const JSON_String *src_string = json_value_get_string_desc(value);
            char *dup_chars = NULL;
            if (src_string == NULL || src_string->chars == NULL) {
                return NULL;
            }
            dup_chars = parson_strndup(src_string->chars, src_string->length);
            if (dup_chars == NULL) {
                return NULL;
            }
            copy = json_value_init_string_no_copy(dup_chars, src_string->length);
            if (copy == NULL) {
                parson_free(dup_chars);
                return NULL;
            }
            break;
        }
        case JSONArray: {
            JSON_Array *src_array = json_value_get_array(value);
            JSON_Array *dst_array = NULL;
            size_t i;
            size_t count;

            if (src_array == NULL) {
                return NULL;
            }

            copy = json_value_init_array();
            if (copy == NULL) {
                return NULL;
            }

            dst_array = json_value_get_array(copy);
            count = json_array_get_count(src_array);

            for (i = 0; i < count; i++) {
                JSON_Value *src_item = json_array_get_value(src_array, i);
                JSON_Value *copied_item = json_value_deep_copy(src_item);
                if (copied_item == NULL) {
                    json_value_free(copy);
                    return NULL;
                }
                if (json_array_add(dst_array, copied_item) != JSONSuccess) {
                    json_value_free(copied_item);
                    json_value_free(copy);
                    return NULL;
                }
            }
            break;
        }
        case JSONObject: {
            JSON_Object *src_object = json_value_get_object(value);
            JSON_Object *dst_object = NULL;
            size_t i;
            size_t count;

            if (src_object == NULL) {
                return NULL;
            }

            copy = json_value_init_object();
            if (copy == NULL) {
                return NULL;
            }

            dst_object = json_value_get_object(copy);
            count = json_object_get_count(src_object);

            for (i = 0; i < count; i++) {
                const char *src_name = json_object_get_name(src_object, i);
                JSON_Value *src_member = json_object_get_value(src_object, src_name);
                JSON_Value *copied_member = NULL;
                char *dup_name = NULL;

                if (src_name == NULL) {
                    json_value_free(copy);
                    return NULL;
                }

                copied_member = json_value_deep_copy(src_member);
                if (copied_member == NULL) {
                    json_value_free(copy);
                    return NULL;
                }

                dup_name = parson_strdup(src_name);
                if (dup_name == NULL) {
                    json_value_free(copied_member);
                    json_value_free(copy);
                    return NULL;
                }

                if (json_object_add(dst_object, dup_name, copied_member) != JSONSuccess) {
                    parson_free(dup_name);
                    json_value_free(copied_member);
                    json_value_free(copy);
                    return NULL;
                }
            }
            break;
        }
        default:
            return NULL;
    }

    return copy;
}
