sds sdsMakeRoomFor(sds s, size_t addlen)
{
    size_t avail = sdsavail(s);
    size_t len = sdslen(s);
    size_t newlen = len + addlen;

    if (avail >= addlen)
        return s;

    size_t oldcap = len + avail;
    size_t newcap;

    if (newlen < SDS_MAX_PREALLOC)
        newcap = newlen * 2;
    else
        newcap = newlen + SDS_MAX_PREALLOC;

    char oldtype = s[-1] & SDS_TYPE_MASK;
    char newtype = sdsReqType(newcap);

    if (oldtype == newtype) {
        size_t hdrlen = sdsHdrSize(oldtype);
        unsigned char *newsh = s_realloc(s - hdrlen, hdrlen + newcap + 1);
        if (newsh == NULL)
            return NULL;
        s = (char *)(newsh + hdrlen);
        sdssetalloc(s, newcap);
    } else {
        size_t oldhdrlen = sdsHdrSize(oldtype);
        size_t newhdrlen = sdsHdrSize(newtype);
        unsigned char *newsh = s_malloc(newhdrlen + newcap + 1);
        if (newsh == NULL)
            return NULL;
        char *news = (char *)(newsh + newhdrlen);
        memcpy(news, s, len + 1);
        s_free(s - oldhdrlen);
        s = news;
        s[-1] = newtype;
        sdssetlen(s, len);
        sdssetalloc(s, newcap);
    }

    return s;
}
