void sdsIncrLen(sds s, ssize_t incr) {
    unsigned char flags = s[-1];
    unsigned char type = flags & SDS_TYPE_MASK;

    if (type == SDS_TYPE_5) {
        uint8_t old_len = SDS_TYPE_5_LEN(flags);
        assert(incr >= 0 || (ssize_t)old_len >= -incr);
        uint8_t new_len = (uint8_t)(old_len + incr);
        s[-1] = (unsigned char)((new_len << SDS_TYPE_BITS) | (flags & SDS_TYPE_MASK));
        s[new_len] = '\0';
    } else if (type == SDS_TYPE_8) {
        SDS_HDR_VAR(8, s);
        assert(incr >= 0 || (ssize_t)sh->len >= -incr);
        assert(incr <= 0 || (uint64_t)(sh->alloc - sh->len) >= (uint64_t)incr);
        sh->len = (uint8_t)(sh->len + incr);
        s[sh->len] = '\0';
    } else if (type == SDS_TYPE_16) {
        SDS_HDR_VAR(16, s);
        assert(incr >= 0 || (ssize_t)sh->len >= -incr);
        assert(incr <= 0 || (uint64_t)(sh->alloc - sh->len) >= (uint64_t)incr);
        sh->len = (uint16_t)(sh->len + incr);
        s[sh->len] = '\0';
