        assert(incr >= 0 || (ssize_t)sh->len >= -incr);
        assert(incr <= 0 || (uint64_t)(sh->alloc - sh->len) >= (uint64_t)incr);
        sh->len = (uint32_t)(sh->len + incr);
        s[sh->len] = '\0';
    } else {
        SDS_HDR_VAR(64, s);
        assert(incr >= 0 || (ssize_t)sh->len >= -incr);
        assert(incr <= 0 || (sh->alloc - sh->len) >= (uint64_t)incr);
        sh->len = (uint64_t)(sh->len + incr);
