int sdsll2str(char *s, long long value)
{
    unsigned long long uv;
    char tmp[21];
    int pos = 0, len = 0;

    if (value < 0) {
        s[len++] = '-';
        uv = (unsigned long long)(-(value + 1)) + 1ULL;
    } else {
        uv = (unsigned long long)value;
    }

    do {
        tmp[pos++] = '0' + (uv % 10ULL);
        uv /= 10ULL;
    } while (uv > 0);

    while (pos > 0) {
        s[len++] = tmp[--pos];
    }

    s[len] = '\0';
    return len;
}
