int sdsull2str(char *s, unsigned long long v) {
    char tmp[20];
    int len = 0;

    if (v == 0) {
        s[0] = '0';
        s[1] = '\0';
        return 1;
    }

    while (v > 0) {
        tmp[len++] = '0' + (v % 10);
        v /= 10;
    }

    for (int i = 0; i < len; i++) {
        s[i] = tmp[len - 1 - i];
    }
    s[len] = '\0';

    return len;
}
