static double fac(double a)
{
    if (isnan(a) || a < 0.0)
        return NAN;

    if (a > (double)UINT_MAX)
        return INFINITY;

    unsigned int n = (unsigned int)a;
    unsigned long long result = 1ULL;

    for (unsigned int i = 1; i <= n; ++i) {
        if (result > ULLONG_MAX / i)
            return INFINITY;
        result *= i;
    }

    return (double)result;
}
