static double ncr(double n, double r)
{
    if (!isfinite(n) || !isfinite(r) || n < 0.0 || r < 0.0 || n < r)
        return NAN;

    if (n > (double)UINT32_MAX || r > (double)UINT32_MAX)
        return INFINITY;

    unsigned long long int N = (unsigned long long int)n;
    unsigned long long int R = (unsigned long long int)r;

    if (R > N - R)
        R = N - R;

    unsigned long long int result = 1;
    for (unsigned long long int i = 1; i <= R; i++) {
        unsigned long long int d = i;
        unsigned long long int g = gcd(result, d);
        result /= g;
        d /= g;

        if (result > ULLONG_MAX / (N - R + i))
            return INFINITY;

        result *= (N - R + i);
        result /= d;
    }

    return (double)result;
}
