static double parse_number(state *s)
{
    const char *p = s->next;
    const char *start = p;
    double value = 0.0;
    int is_hex = 0;

    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
        is_hex = 1;
        p += 2;
        if (!isxdigit((unsigned char)*p)) {
            s->type = TOK_ERROR;
            return 0.0;
        }
        while (isxdigit((unsigned char)*p)) {
            int digit;
            if (*p >= '0' && *p <= '9')
                digit = *p - '0';
            else if (*p >= 'a' && *p <= 'f')
                digit = *p - 'a' + 10;
            else
                digit = *p - 'A' + 10;
            value = value * 16.0 + digit;
            p++;
        }
    } else {
        int has_digits = 0;
        while (isdigit((unsigned char)*p)) {
            value = value * 10.0 + (*p - '0');
            p++;
            has_digits = 1;
        }
        if (*p == '.') {
            const char *frac_start = p;
            p++;
            if (!isdigit((unsigned char)*p) && !has_digits) {
                s->type = TOK_ERROR;
                return 0.0;
            }
            double frac = 0.0;
            double scale = 0.1;
            while (isdigit((unsigned char)*p)) {
                frac += (*p - '0') * scale;
                scale *= 0.1;
                p++;
                has_digits = 1;
            }
            value += frac;
            (void)frac_start;
        }
        if (!has_digits) {
            s->type = TOK_ERROR;
            return 0.0;
        }
        if (*p == 'e' || *p == 'E') {
            const char *exp_start = p;
            p++;
            int exp_sign = 1;
            if (*p == '+' || *p == '-') {
                if (*p == '-') exp_sign = -1;
                p++;
            }
            if (!isdigit((unsigned char)*p)) {
                p = exp_start;
            } else {
                int exp_val = 0;
                while (isdigit((unsigned char)*p)) {
                    exp_val = exp_val * 10 + (*p - '0');
                    p++;
                }
                value *= pow(10.0, exp_sign * exp_val);
            }
        }
    }

    s->next = p;
    s->type = TOK_NUMBER;
    return value;
}
