```c
static void next_token(state *s)
{
    s->type = TOK_NULL;
    s->prec = PREC_NONE;

    while (*s->next) {
        char c = *s->next;

        if (isdigit((unsigned char)c) || c == '.') {
            s->value = parse_number(s);
            s->type = TOK_NUMBER;
            return;
        }

        if (isalpha((unsigned char)c)) {
            const char *start = s->next;
            int len = 0;
            const te_variable *var;

            while (isalnum((unsigned char)*s->next) || *s->next == '_') {
                s->next++;
                len++;
            }

            var = find_lookup(s, start, len);
            if (!var)
                var = find_builtin(start, len);

            if (!var) {
                s->type = TOK_ERROR;
                return;
            }

            if (var->type == TE_VARIABLE) {
                s->type = TOK_VARIABLE;
                s->bound = (const double *)var->address;
                return;
            }

            if (IS_FUNCTION(var->type) || IS_CLOSURE(var->type)) {
                s->type = var->type;
                s->function = var->address;
                if (IS_CLOSURE(var->type))
                    s->context = var->context;
                return;
            }

            s->type = TOK_ERROR;
            return;
        }

        switch (c) {
            case ' ':
            case '\t':
            case '\n':
            case '\r':
                s->next++;
                continue;

            case '+':
                s->next++;
                infix(s, add, PREC_SUM);
                return;

            case '-':
                s->next++;
                infix(s, sub, PREC_SUM);
                return;

            case '*':
                s->next++;
                infix(s, mul, PREC_TERM);
                return;

            case '/':
                s->next++;
                infix(s, divide, PREC_TERM);
                return;

            case '^':
                s->next++;
                infix(s, pow, PREC_POW);
                return;

            case '=':
                s->next++;
                if (match(s, '=')) {
                    infix(s, equal, PREC_EQ);
                } else {
                    s->type = TOK_ERROR;
                }
                return;

            case '!':
                s->next++;
                if (match(s, '=')) {
                    infix(s, not_equal, PREC_EQ);
                } else {
                    s->type = TOK_ERROR;
                }
                return;

            case '<':
                s->next++;
                if (match(s, '=')) {
                    infix(s, lower_eq, PREC_REL);
                } else {
                    infix(s, lower, PREC_REL);
                }
                return;

            case '>':
                s->next++;
                if (match(s, '=')) {
                    infix(s, greater_eq, PREC_REL);
                } else {
                    infix(s, greater, PREC_REL);
                }
                return;

            case '&':
                s->next++;
                if (match(s, '&')) {
                    infix(s, logical_and, PREC_AND);
                } else {
                    s->type = TOK_ERROR;
                }
                return;

            case '|':
                s->next++;
                if (match(s, '|')) {
                    infix(s, logical_or, PREC_OR);
                } else {
                    s->type = TOK_ERROR;
                }
                return;

            case '(':
                s->next++;
                s->type = TOK_OPEN;
                return;

            case ')':
                s->next++;
                s->type = TOK_CLOSE;
                return;

            case ',':
                s->next++;
                s->type = TOK_SEP;
                s->function = comma;
                s->prec = PREC_LIST;
                return;

            default:
                s->next++;
                s->type = TOK_ERROR;
                return;
        }
    }

    s->type = TOK_END;
}
