```c
static te_expr *base(state *s)
{
    te_expr *ret;
    int arity;
    int is_closure;
    int i;
    const te_expr *params[8];

    switch (TYPE_MASK(s->type)) {
        case TE_VARIABLE:
            ret = new_expr(TE_VARIABLE, NULL);
            CHECK_NULL(ret);
            ret->bound = s->bound;
            next_token(s);
            break;

        case TE_CONSTANT:
            ret = new_expr(TE_CONSTANT, NULL);
            CHECK_NULL(ret);
            ret->value = s->value;
            next_token(s);
            break;

        case TE_FUNCTION0: case TE_FUNCTION1: case TE_FUNCTION2: case TE_FUNCTION3:
        case TE_FUNCTION4: case TE_FUNCTION5: case TE_FUNCTION6: case TE_FUNCTION7:
        case TE_CLOSURE0: case TE_CLOSURE1: case TE_CLOSURE2: case TE_CLOSURE3:
        case TE_CLOSURE4: case TE_CLOSURE5: case TE_CLOSURE6: case TE_CLOSURE7:
            arity = ARITY(s->type);
            is_closure = IS_CLOSURE(s->type);

            ret = new_expr(s->type, NULL);
            CHECK_NULL(ret);
            ret->function = s->function;

            if (is_closure) {
                params[arity] = (const te_expr *)s->context;
            }

            next_token(s);

            if (arity == 0) {
                if (s->type == TOK_OPEN) {
                    next_token(s);
                    if (s->type != TOK_CLOSE) {
                        s->type = TOK_ERROR;
                    } else {
                        next_token(s);
                    }
                }
            } else if (arity == 1) {
                if (s->type != TOK_OPEN) {
                    s->type = TOK_ERROR;
                } else {
                    next_token(s);
                    params[0] = power(s);
                    if (s->type != TOK_CLOSE) {
                        s->type = TOK_ERROR;
                    } else {
                        next_token(s);
                    }
                }
            } else {
                if (s->type != TOK_OPEN) {
                    s->type = TOK_ERROR;
                } else {
                    next_token(s);
                    for (i = 0; i < arity; i++) {
                        params[i] = binary(s, PREC_OR);
                        if (i < arity - 1) {
                            if (s->type != TOK_SEP) {
                                s->type = TOK_ERROR;
                                break;
                            }
                            next_token(s);
                        }
                    }
                    if (s->type != TOK_CLOSE) {
                        s->type = TOK_ERROR;
                    } else {
                        next_token(s);
                    }
                }
            }

            if (is_closure) {
                ret = new_expr(s->type, params);
                CHECK_NULL(ret);
                ret->function = s->function;
            } else {
                ret = new_expr(s->type, params);
                CHECK_NULL(ret);
                ret->function = s->function;
            }
            break;

        case TOK_OPEN:
            next_token(s);
            ret = binary(s, PREC_LIST);
            if (s->type != TOK_CLOSE) {
                s->type = TOK_ERROR;
            } else {
                next_token(s);
            }
            break;

        default:
            ret = new_expr(0, NULL);
            CHECK_NULL(ret);
            ret->value = NAN;
            s->type = TOK_ERROR;
            break;
    }

    return ret;
}
