static te_expr *power(state *s)
{
    int sign = 1;
    int logical_count = 0;
    int applied = 0;
    te_expr *expr;

    while (s->type == TOK_INFIX) {
        if (s->function == add) {
            applied = 1;
            next_token(s);
        } else if (s->function == sub) {
            applied = 1;
            if (logical_count == 0) {
                sign = -sign;
            }
            next_token(s);
        } else if (s->function == logical_not) {
            applied = 1;
            logical_count = (logical_count + 1) % 2;
            next_token(s);
        } else {
            break;
        }
    }

    if (s->depth >= TE_MAX_DEPTH) {
        s->type = TOK_ERROR;
        return NULL;
    }

    s->depth++;
    expr = base(s);
    s->depth--;

    if (expr && applied) {
        if (sign < 0 && logical_count == 0) {
            expr = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, negate, expr, NULL);
        } else if (sign > 0 && logical_count == 1) {
            expr = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, logical_not, expr, NULL);
        } else if (sign < 0 && logical_count == 1) {
            expr = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, negate_logical_not, expr, NULL);
        } else if (sign > 0 && logical_count == 0) {
            expr = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, logical_notnot, expr, NULL);
        } else if (sign < 0 && logical_count == 0) {
            expr = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, negate_logical_notnot, expr, NULL);
        }
        s->applied_unary = 1;
    }

    return expr;
}
