static te_expr *binary(state *s, int prec)
{
    te_expr *left = operand(s, prec);
    CHECK_NULL(left);

    while ((s->type == TOK_INFIX || s->type == TOK_SEP) && s->prec == prec) {
        const void *function = s->function;
        next_token(s);

        te_expr *right = operand(s, prec);
        CHECK_NULL(right);

        te_expr *combined = new_fun(TE_FUNCTION2 | TE_FLAG_PURE, function, left, right);
        CHECK_NULL(combined);

        left = combined;
    }

    return left;
}
