double te_eval(const te_expr *n)
{
    if (n == NULL) {
        return NAN;
    }

    int type = TYPE_MASK(n->type);

    if (type == TE_CONSTANT) {
        return n->value;
    }

    if (type == TE_VARIABLE) {
        return *(const double *)n->bound;
    }

    if (type >= TE_FUNCTION0 && type <= TE_FUNCTION7) {
        int arity = type - TE_FUNCTION0;
        double args[7];
        for (int i = 0; i < arity; i++) {
            args[i] = te_eval(n->parameters[i]);
        }
        switch (arity) {
            case 0: return ((double(*)(void))n->function)();
            case 1: return ((double(*)(double))n->function)(args[0]);
            case 2: return ((double(*)(double,double))n->function)(args[0], args[1]);
            case 3: return ((double(*)(double,double,double))n->function)(args[0], args[1], args[2]);
            case 4: return ((double(*)(double,double,double,double))n->function)(args[0], args[1], args[2], args[3]);
            case 5: return ((double(*)(double,double,double,double,double))n->function)(args[0], args[1], args[2], args[3], args[4]);
            case 6: return ((double(*)(double,double,double,double,double,double))n->function)(args[0], args[1], args[2], args[3], args[4], args[5]);
            case 7: return ((double(*)(double,double,double,double,double,double,double))n->function)(args[0], args[1], args[2], args[3], args[4], args[5], args[6]);
        }
    }

    if (type >= TE_CLOSURE0 && type <= TE_CLOSURE7) {
        int arity = type - TE_CLOSURE0;
        double args[7];
        for (int i = 1; i <= arity; i++) {
            args[i - 1] = te_eval(n->parameters[i]);
        }
        switch (arity) {
            case 0: return ((double(*)(const void *))n->function)(n->parameters[0]);
            case 1: return ((double(*)(const void *, double))n->function)(n->parameters[0], args[0]);
            case 2: return ((double(*)(const void *, double, double))n->function)(n->parameters[0], args[0], args[1]);
            case 3: return ((double(*)(const void *, double, double, double))n->function)(n->parameters[0], args[0], args[1], args[2]);
            case 4: return ((double(*)(const void *, double, double, double, double))n->function)(n->parameters[0], args[0], args[1], args[2], args[3]);
            case 5: return ((double(*)(const void *, double, double, double, double, double))n->function)(n->parameters[0], args[0], args[1], args[2], args[3], args[4]);
            case 6: return ((double(*)(const void *, double, double, double, double, double, double))n->function)(n->parameters[0], args[0], args[1], args[2], args[3], args[4], args[5]);
            case 7: return ((double(*)(const void *, double, double, double, double, double, double, double))n->function)(n->parameters[0], args[0], args[1], args[2], args[3], args[4], args[5], args[6]);
        }
    }

    return NAN;
