static void optimize(te_expr *n)
{
    if (!IS_PURE(n->type)) {
        return;
    }

    int arity = ARITY(n->type);
    int all_constants = 1;

    for (int i = 0; i < arity; ++i) {
        optimize(n->parameters[i]);
        if (((te_expr *)n->parameters[i])->type != TE_CONSTANT) {
            all_constants = 0;
        }
    }

    if (!all_constants) {
        return;
    }

    double value = te_eval(n);
    te_free_parameters(n);
    n->type = TE_CONSTANT;
    n->value = value;
}
