te_expr *te_compile(const char *expression, const te_variable *variables, int var_count, int *error)
{
    state s;
    te_expr *root = NULL;
    int err = 0;

    if (error) *error = -1;

    if (!expression) {
        return NULL;
    }

    s.next = expression;
    s.type = TOK_NULL;
    s.prec = PREC_NONE;
    s.value = 0.0;
    s.bound = NULL;
    s.function = NULL;
    s.context = NULL;
    s.lookup = variables;
    s.lookup_len = var_count;
    s.applied_unary = 0;
    s.depth = 0;

    next_token(&s);

    if (s.type == TOK_END) {
        if (error) *error = -1;
        return NULL;
    }

    root = binary(&s, PREC_NONE);

    if (!root) {
        if (error) {
            if (s.next == expression) {
                *error = -1;
            } else {
