int vec_compact_(char **data, int *length, int *capacity, int memsz)
{
    if (*length == 0) {
        free(*data);
        *data = NULL;
        *capacity = 0;
        return 0;
    }

    char *new_data = realloc(*data, (size_t)(*length) * (size_t)memsz);
    if (new_data == NULL) {
        return -1;
    }

    *data = new_data;
    *capacity = *length;
    return 0;
}
