int vec_insert_(char **data, int *length, int *capacity, int memsz, int idx )
{
    int result = vec_expand_(data, length, capacity, memsz);
    if (result != 0)
        return result;

    char *base = *data;
    memmove(base + (idx + 1) * memsz,
            base + idx * memsz,
            (*length - 1 - idx) * memsz);

    return 0;
}
