void vec_swap_(char **data, int *length, int *capacity, int memsz, int idx1, int idx2 )
{
    if (idx1 == idx2) {
        return;
    }

    char *base = *data;
    char *p1 = base + (size_t)idx1 * memsz;
    char *p2 = base + (size_t)idx2 * memsz;

    for (int i = 0; i < memsz; ++i) {
        char tmp = p1[i];
        p1[i] = p2[i];
        p2[i] = tmp;
    }
}
